// Backend (extending this lesson's minimal version with persistence)
import { MongoClient } from 'mongodb';

let submissionsCollection;

async function startServer() {
  const client = new MongoClient(process.env.DATABASE_URL);
  await client.connect();
  submissionsCollection = client.db('portfolio').collection('submissions');
  app.listen(process.env.PORT || 3001);
}

app.post('/api/contact', async (req, res, next) => {
  try {
    const { name, email, message } = req.body;
    if (!name || !email || !message) {
      return res.status(400).json({ success: false, error: 'All fields are required' });
    }

    await submissionsCollection.insertOne({ name, email, message, createdAt: new Date() });
    res.status(201).json({ success: true, data: { received: true } });
  } catch (err) {
    next(err);
  }
});

startServer();

// Frontend - replacing Stage 5's form submit handler's TODO comment
form.addEventListener('submit', async function (event) {
  event.preventDefault();
  if (!isValidEmail(emailInput.value)) {
    emailInput.classList.add('border-red-500');
    return;
  }

  try {
    const response = await fetch('https://your-deployed-backend.example.com/api/contact', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: form.name.value,
        email: form.email.value,
        message: form.message.value
      })
    });

    if (!response.ok) throw new Error('Submission failed');

    form.reset();
    alert('Thank you! Your message has been sent.');
  } catch (err) {
    alert('Something went wrong. Please try again.');
  }
});

