// Backend CORS config:
app.use(cors({ origin: 'http://localhost:3000' }));

// Frontend fetch URL:
fetch('http://localhost:3001/api/contact', { ... });


// AFTER (production - what this stage requires you to update):

// Backend CORS config - updated to your REAL deployed frontend URL:
app.use(cors({ origin: 'https://your-actual-site.netlify.app' }));

// Frontend - using an environment variable (Module 10 lesson 6)
// instead of a hardcoded URL, so the SAME code works correctly in
// both environments without ever needing to be manually edited again:
const BACKEND_URL = import.meta.env.VITE_BACKEND_URL;
fetch(`${BACKEND_URL}/api/contact`, { ... });

// .env (local): VITE_BACKEND_URL=http://localhost:3001
// Production environment variable (configured on the hosting platform
// itself, NOT in a committed file): VITE_BACKEND_URL=https://your-actual-backend.example-host.com
